/// <summary>
/// The <c>AVAWHSControlCoilOutsideDiameter</c> class is responsible for handling the coil outside Diameter
/// </summary>
#AVAWHSRF
[
    WhsControlFactory(#AVACoilOutsideDiameter)
]
public class AVAWHSControlCoilOutsideDiameter extends WhsControl
{
}

Method.Source:
public boolean process()
{
    if (this.parmData())
    {
        fieldValues.insert(#AVACoilOutsideDiameter, this.parmData());
    }
    return super();
}

public boolean canProcessDefaultValue()
{
    if (this.parmData())
    {
        return true;
    }

    return false;
}
